#!/usr/bin/env bash
# {{NAME}} — generated by TERMy ({{LANG}})
# {{ARRAY}} expands to bare words → a proper bash array below.
set -euo pipefail

linear_search() {
    local target="$1"; shift
    local arr=("$@") i
    for i in "${!arr[@]}"; do
        if [[ "${arr[$i]}" == "$target" ]]; then
            printf 'Found %s at index %s\n' "$target" "$i"; return 0
        fi
    done
    printf '%s not found in [%s]\n' "$target" "${arr[*]}"; return 1
}

linear_search {{TARGET}} {{ARRAY}}